-- Fakt kartochkalarining ruscha matni — 5-partiya:
-- Abu Nasr Forobiy, Abu Rayhon Beruniy va Ahmad al-Farg'oniy.

-- ===== Abu Nasr Forobiy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Абу Наср аль-Фараби?', fact_ru = 'Я родился в 873 году в городе Фараб. Моё полное имя — Абу Наср Мухаммад ибн Мухаммад ибн Узлуг Тархан аль-Фараби.' WHERE id = 191;
UPDATE fact_cards SET topic_ru = '«Второй учитель»', question_ru = 'Почему аль-Фараби называли «Вторым учителем»?', fact_ru = 'Мир считает Аристотеля первым учителем, а меня назвали «Муаллим ас-сани» — «Вторым учителем».' WHERE id = 192;
UPDATE fact_cards SET topic_ru = 'Моя учёба', question_ru = 'В каких городах учился Абу Наср аль-Фараби?', fact_ru = 'Начальное образование я получил на родине, затем учился в Ташкенте, Бухаре и Самарканде.' WHERE id = 193;
UPDATE fact_cards SET topic_ru = 'Мои странствия', question_ru = 'В каких городах побывал Абу Наср аль-Фараби?', fact_ru = 'Я побывал в городах Багдад, Исфахан, Хамадан и Рей.' WHERE id = 194;
UPDATE fact_cards SET topic_ru = 'Языки', question_ru = 'Сколько языков знал Абу Наср аль-Фараби?', fact_ru = 'Я знал более семидесяти языков.' WHERE id = 195;
UPDATE fact_cards SET topic_ru = 'Мои науки', question_ru = 'Какими науками занимался Абу Наср аль-Фараби?', fact_ru = 'Я занимался философией, арифметикой, геометрией, астрономией, музыкой, физикой, химией, оптикой, медициной и биологией.' WHERE id = 196;
UPDATE fact_cards SET topic_ru = 'Число моих трудов', question_ru = 'Сколько трудов написал аль-Фараби и сколько дошло до нас?', fact_ru = 'Я написал более 160 трудов, до нас дошли около сорока.' WHERE id = 197;
UPDATE fact_cards SET topic_ru = 'Наука о музыке', question_ru = 'Была ли наука о музыке среди занятий аль-Фараби?', fact_ru = 'Наука о музыке была одной из наук, которыми я занимался.' WHERE id = 198;
UPDATE fact_cards SET topic_ru = 'Моя кончина', question_ru = 'Когда и где умер Абу Наср аль-Фараби?', fact_ru = 'Я скончался в 950 году в городе Дамаск.' WHERE id = 199;
UPDATE fact_cards SET topic_ru = 'Моё имя', question_ru = 'От названия какого города взято имя аль-Фараби?', fact_ru = 'Слово «аль-Фараби» в моём полном имени взято от названия города Фараб, где я родился.' WHERE id = 200;
UPDATE fact_cards SET topic_ru = 'Город добродетельных', question_ru = 'О чём труд аль-Фараби «Город добродетельных людей»?', fact_ru = 'Один из самых известных моих трудов — «Город добродетельных людей». В нём я написал о справедливом и просвещённом городе, где люди помогают друг другу.' WHERE id = 1461;
UPDATE fact_cards SET topic_ru = 'Мои комментарии к Аристотелю', question_ru = 'К трудам какого греческого философа аль-Фараби писал комментарии?', fact_ru = 'Я писал комментарии к трудам греческого философа Аристотеля. Благодаря этим комментариям многие учёные постигли его науку.' WHERE id = 1462;
UPDATE fact_cards SET topic_ru = 'Классификация наук', question_ru = 'Как аль-Фараби назвал труд, в котором классифицировал науки?', fact_ru = 'В труде «Ихса аль-улум» — «Классификация наук» — я по порядку разделил на группы науки своего времени.' WHERE id = 1463;
UPDATE fact_cards SET topic_ru = 'Наука логики', question_ru = 'Учителем какой науки считали аль-Фараби?', fact_ru = 'Я написал множество трактатов по логике. За то, что я учил правилам верного мышления, меня считали учителем логики.' WHERE id = 1464;
UPDATE fact_cards SET topic_ru = 'О счастье', question_ru = 'Какой труд аль-Фараби написал о достижении счастья?', fact_ru = 'В трактате «О достижении счастья» я объяснил, что к счастью человека ведут знание и добрый нрав.' WHERE id = 1465;
UPDATE fact_cards SET topic_ru = 'Почёт правителя', question_ru = 'Какой правитель Алеппо ценил знания аль-Фараби?', fact_ru = 'Правитель Алеппо Сайф ад-Даула пригласил меня к своему двору и очень ценил мои знания.' WHERE id = 1466;
UPDATE fact_cards SET topic_ru = 'Моя память', question_ru = 'Какой знаменитый университет назван именем аль-Фараби?', fact_ru = 'Национальному университету в казахстанском городе Алматы присвоено имя аль-Фараби. Так моё имя чтят и сегодня.' WHERE id = 1467;

-- ===== Abu Rayhon Beruniy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Абу Райхан Беруни?', fact_ru = 'Я родился в 973 году близ хорезмского города Кят.' WHERE id = 151;
UPDATE fact_cards SET topic_ru = 'Труд об Индии', question_ru = 'Что написано в труде Беруни «Индия»?', fact_ru = 'В труде «Индия» я описал религию, обычаи и науки народа этой страны так, как видел их сам. Ради этого я выучил санскрит.' WHERE id = 152;
UPDATE fact_cards SET topic_ru = 'Измерение Земли', question_ru = 'Как Беруни измерил радиус земного шара?', fact_ru = 'Измерив с высоты горы угол горизонта, я вычислил радиус земного шара. Мой результат оказался очень близок к нынешнему значению.' WHERE id = 153;
UPDATE fact_cards SET topic_ru = 'Число моих трудов', question_ru = 'Сколько трудов написал Абу Райхан Беруни?', fact_ru = 'За свою жизнь я написал более 150 трудов по астрономии, географии, истории, минералогии и медицине.' WHERE id = 154;
UPDATE fact_cards SET topic_ru = '«Памятники минувших поколений»', question_ru = 'О чём труд Беруни «Памятники минувших поколений»?', fact_ru = 'В этом труде я сопоставил календари, праздники и летосчисление разных народов.' WHERE id = 155;
UPDATE fact_cards SET topic_ru = 'Академия Мамуна', question_ru = 'В какой академии работал Абу Райхан Беруни в юности?', fact_ru = 'В юности я работал в столице Хорезма Гургандже, в кругу учёных при дворе хорезмшаха Мамуна — в Академии Мамуна. Там собрались многие знаменитые учёные того времени.' WHERE id = 1468;
UPDATE fact_cards SET topic_ru = 'Моя переписка с Ибн Синой', question_ru = 'С каким великим учёным Беруни вёл научную переписку?', fact_ru = 'С молодым Ибн Синой мы вели научный спор в письмах: я посылал ему вопросы о природе, а он писал ответы. Эта переписка знаменита в истории науки.' WHERE id = 1469;
UPDATE fact_cards SET topic_ru = 'Мои годы в Газни', question_ru = 'В каком городе жил Беруни начиная с 1017 года?', fact_ru = 'В 1017 году, заняв Хорезм, Махмуд Газневи увёз меня в город Газни. Большая часть моей жизни прошла там за научными трудами.' WHERE id = 1470;
UPDATE fact_cards SET topic_ru = '«Канон Масуда»', question_ru = 'Как называется крупнейший труд Беруни по астрономии?', fact_ru = 'Мой самый большой труд по астрономии называется «Канон Масуда». Я посвятил его султану Масуду и подробно изложил в нём науку о звёздах.' WHERE id = 1471;
UPDATE fact_cards SET topic_ru = 'Моя книга о минералах', question_ru = 'Какую книгу Беруни написал о драгоценных камнях?', fact_ru = 'В книге под названием «Минералогия» я описал драгоценные камни и руды, точно измерил их вес и свойства.' WHERE id = 1472;
UPDATE fact_cards SET topic_ru = 'Мой труд «Сайдана»', question_ru = 'Какой труд по лекарствоведению Беруни написал в конце жизни?', fact_ru = 'В конце жизни я написал труд «Сайдана». В нём я привёл названия лекарственных растений и снадобий на разных языках и объяснил их пользу.' WHERE id = 1473;
UPDATE fact_cards SET topic_ru = 'Знание языков', question_ru = 'Какие языки знал Абу Райхан Беруни?', fact_ru = 'Кроме родного хорезмийского я изучил арабский, персидский, санскрит и греческий. Благодаря этому я мог читать книги разных народов в подлиннике.' WHERE id = 1474;
UPDATE fact_cards SET topic_ru = 'Как я сделал глобус', question_ru = 'Какое научное устройство Беруни изготовил в юности?', fact_ru = 'В юности я изготовил глобус с изображением земной поверхности. На нём я показал расположение городов и морей.' WHERE id = 1475;
UPDATE fact_cards SET topic_ru = 'Значение моего имени', question_ru = 'Что означает слово «Беруни» в имени Абу Райхана Беруни?', fact_ru = 'Имя «Беруни» взято от персидского слова «берун» — «снаружи» — и означает «человек из-за городской черты».' WHERE id = 1476;
UPDATE fact_cards SET topic_ru = 'Места, названные моим именем', question_ru = 'Какие места названы именем Абу Райхана Беруни?', fact_ru = 'Один город в Каракалпакстане называется Беруни. В Ташкенте есть станция метро моего имени, а один из кратеров на Луне тоже носит моё имя.' WHERE id = 1477;

-- ===== Ahmad al-Farg'oniy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Где родился Ахмад аль-Фергани и в каком веке он жил?', fact_ru = 'Я родился в Фергане. Моё полное имя — Абуль Аббас Ахмад ибн Мухаммад ибн Касир аль-Фергани. Жил и творил я в IX веке.' WHERE id = 181;
UPDATE fact_cards SET topic_ru = 'Моя работа в Багдаде', question_ru = 'С каким городом связана творческая деятельность Ахмада аль-Фергани?', fact_ru = 'Моя творческая деятельность была связана с Багдадом, с «Байт уль-хикма» под руководством аль-Хорезми.' WHERE id = 182;
UPDATE fact_cards SET topic_ru = 'Обсерватории', question_ru = 'В строительстве обсерваторий в каких городах участвовал аль-Фергани?', fact_ru = 'Я участвовал в строительстве обсерваторий в Багдаде и Дамаске.' WHERE id = 183;
UPDATE fact_cards SET topic_ru = 'Таблица Птолемея', question_ru = 'Чью звёздную таблицу проверил Ахмад аль-Фергани?', fact_ru = 'Я проверил сведения из «Таблицы звёзд» Птолемея.' WHERE id = 184;
UPDATE fact_cards SET topic_ru = 'Солнечное затмение', question_ru = 'Затмение какого года Ахмад аль-Фергани предсказал заранее?', fact_ru = 'Я заранее предсказал солнечное затмение 812 года.' WHERE id = 185;
UPDATE fact_cards SET topic_ru = 'Форма Земли', question_ru = 'Что Ахмад аль-Фергани открыл о форме Земли?', fact_ru = 'Я доказал, что Земля круглая.' WHERE id = 186;
UPDATE fact_cards SET topic_ru = 'Ниломер', question_ru = 'Какой прибор аль-Фергани создал в Египте?', fact_ru = 'В Египте я создал прибор для измерения уровня воды в реке Нил.' WHERE id = 187;
UPDATE fact_cards SET topic_ru = 'Моё имя в Европе', question_ru = 'Каким именем европейцы называли Ахмада аль-Фергани?', fact_ru = 'Европейцы называли меня «Альфраганус».' WHERE id = 188;
UPDATE fact_cards SET topic_ru = 'Мои труды', question_ru = 'Сколько трудов Ахмада аль-Фергани сохранилось?', fact_ru = 'Сохранилось семь моих трудов. Среди них «Книга о небесных движениях и общей науке о звёздах» (Основы астрономии), «Книга об изготовлении астролябии» и «Исчисление семи климатов».' WHERE id = 189;
UPDATE fact_cards SET topic_ru = 'Моя память', question_ru = 'Когда отмечалось 1200-летие Ахмада аль-Фергани?', fact_ru = 'Я умер в 867 году. Много веков спустя, в 1998 году, 1200-летие со дня моего рождения отмечалось на международном уровне, и в городе Кува мне поставили памятник. То, что память обо мне живёт, очень меня радует.' WHERE id = 190;
UPDATE fact_cards SET topic_ru = 'Латинские переводы', question_ru = 'Для чего книга аль-Фергани использовалась в европейских университетах?', fact_ru = 'Мой главный труд по астрономии перевели на латынь в XII веке. Несколько веков его преподавали в европейских университетах как учебник астрономии.' WHERE id = 1488;
UPDATE fact_cards SET topic_ru = 'В трудах Данте', question_ru = 'Какой знаменитый итальянский поэт пользовался сведениями аль-Фергани?', fact_ru = 'Знаменитый итальянский поэт Данте, когда писал в своих произведениях о науке о небе, пользовался сведениями из моей книги.' WHERE id = 1489;
UPDATE fact_cards SET topic_ru = 'Расчёты Колумба', question_ru = 'Какой знаменитый путешественник пользовался расчётами аль-Фергани?', fact_ru = 'Путешественник Христофор Колумб тоже опирался на сведения из моего труда, когда вычислял размеры Земли.' WHERE id = 1490;
UPDATE fact_cards SET topic_ru = 'Мой труд об астролябии', question_ru = 'О каком астрономическом приборе аль-Фергани написал труд?', fact_ru = 'Я написал особый труд об астролябии — приборе для измерения высоты звёзд. В нём я объяснил устройство и изготовление этого прибора.' WHERE id = 1491;
UPDATE fact_cards SET topic_ru = 'Исчисление планет', question_ru = 'Какие сведения о планетах привёл аль-Фергани в своей книге?', fact_ru = 'В своей книге я привёл расчёты расстояний до планет и их величин. Этими числами европейские учёные пользовались долгое время.' WHERE id = 1492;
UPDATE fact_cards SET topic_ru = 'Кратер на Луне', question_ru = 'Какой кратер на Луне назван именем Ахмада аль-Фергани?', fact_ru = 'Одному из кратеров на Луне дано имя «Альфраганус» — моё имя в Европе. Посмотришь на небо — и можешь вспомнить обо мне!' WHERE id = 1493;
UPDATE fact_cards SET topic_ru = 'Мой 1200-летний юбилей', question_ru = 'Когда отмечалось 1200-летие со дня рождения Ахмада аль-Фергани?', fact_ru = 'Я умер в 867 году. Более тысячи лет спустя, в 1998 году, широко отмечалось 1200-летие со дня моего рождения. По этому случаю в городах Фергана и Кува мне поставили памятники — это был мой 1200-летний юбилей!' WHERE id = 1494;
